export function TimelineView(e,n){return`\n        <div class="isro-timeline">\n            ${e.map(e=>{const i=n[e.type]||{label:e.type,color:"#888"};return`\n            <div class="timeline-event" data-type="${e.type}">\n                <div class="timeline-dot" style="background: ${i.color}"></div>\n                <div class="timeline-content">\n                    <div class="timeline-meta">\n                        <span class="timeline-year">${e.year}</span>\n                        <span class="timeline-cat-badge" style="background: ${i.color}20; color: ${i.color}">${i.label}</span>\n                    </div>\n                    <p class="timeline-text">${e.event}</p>\n                </div>\n            </div>\n        `}).join("")}\n        </div>\n    `}